class TestRiskEngine:
    def test_calculate_score_empty(self):
        assert RiskEngine.calculate_score([]) == 0.0

    def test_calculate_score_weighted(self):
        vulns = [
            Vulnerability("1", Severity.CRITICAL, 9.0, "C", {}, "D", "R", "E", confidence=1.0), # 10.0
            Vulnerability("2", Severity.LOW, 2.0, "C", {}, "D", "R", "E", confidence=0.5),      # 1.0 * 0.5 = 0.5
        ]
        # (10.0 + 0.5) / 2 = 5.25
        assert RiskEngine.calculate_score(vulns) == 5.25

class TestNormalizer:
    def test_normalize_valid_data(self):
        raw_data = [{
            "id": "RAW-01",
            "severity": "CRITICAL",
            "cvss": 9.5,
            "category": "XSS",
            "location": {"file": "index.html", "line": 5},
            "description": "desc",
            "remediation": "rem",
            "evidence": "evid",
            "confidence": 0.8
        }]
        normalized = Normalizer.normalize(raw_data, "mock_engine")
        assert len(normalized) == 1
        assert normalized[0].severity == Severity.CRITICAL
        assert normalized[0].confidence == 0.8

