def test_vulnerability_dedup_hash():
    v1 = Vulnerability("ID1", Severity.LOW, 1.0, "Cat1", {"file": "f.py", "line": 10}, "D", "R", "E")
    v2 = Vulnerability("ID1", Severity.LOW, 1.0, "Cat1", {"file": "f.py", "line": 10}, "D", "R", "E")
    v3 = Vulnerability("ID2", Severity.LOW, 1.0, "Cat1", {"file": "f.py", "line": 10}, "D", "R", "E")
    
    assert v1.get_dedup_hash() == v2.get_dedup_hash()
    assert v1.get_dedup_hash() != v3.get_dedup_hash()